import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.B3-dzFNu.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1793482925000}'),n={name:"troubleshooting.md"};function o(r,e,d,l,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with the error printed by Redline and the <code>status.json</code> in the reported artifact directory. Do not post API keys, private configuration files, or unredacted logs when asking for help.</p><h2 id="the-command-is-not-found" tabindex="-1">The command is not found <a class="header-anchor" href="#the-command-is-not-found" aria-label="Permalink to &quot;The command is not found&quot;">​</a></h2><p>Check the prerequisites:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Use Node.js 24. If Redline is installed, run <code>redline --help</code>. Otherwise use <code>node bin/redline.mjs --help</code> from its source checkout. When you are in another repository, use the source binary&#39;s full path or <code>--repository</code>; do not assume <code>bin/redline.mjs</code> exists in the project being reviewed.</p><p>If npm installation returns <code>E404</code>, the requested package/version may not be published or accessible. Use the <a href="/projects/redline/get-started/#use-a-source-checkout">source-checkout instructions</a>. A package-publishing token is not needed to review source.</p><h2 id="no-files-were-reviewed" tabindex="-1">No files were reviewed <a class="header-anchor" href="#no-files-were-reviewed" aria-label="Permalink to &quot;No files were reviewed&quot;">​</a></h2><p>Inspect the target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span></span></code></pre></div><p>The default command reviews uncommitted tracked changes. A clean working tree with commits ahead of main needs a <a href="/projects/redline/commands#review-your-branch-against-main">branch comparison</a>. New untracked files need explicit inclusion. Lock files, generated/vendor paths and binary files can be excluded by review eligibility rules.</p><p>A repository must have a committed <code>HEAD</code>. Resolve merge conflicts and stage or materialize unsupported index states before trying again. See <a href="/projects/redline/local-cli#review-uncommitted-changes">working-tree behavior</a>.</p><h2 id="the-model-rejects-the-request" tabindex="-1">The model rejects the request <a class="header-anchor" href="#the-model-rejects-the-request" aria-label="Permalink to &quot;The model rejects the request&quot;">​</a></h2><p>Check these without printing the credential:</p><ol><li>The selected Pi or OpenCode binary is installed outside the reviewed repository.</li><li>The user configuration is outside the repository and has private permissions.</li><li>The credential-map key matches <code>model-config.provider</code>.</li><li>The endpoint includes the correct API path and the model ID is available there.</li><li>The chosen protocol and token allowance are supported by that provider/model.</li></ol><p>HTTP <code>401</code> or <code>403</code> can indicate credential or access problems. An immediate configuration error is not a timeout; giving it more time will not fix it. Follow the provider&#39;s actual error rather than guessing which setting failed.</p><p>Redline preserves provider/model reasoning defaults. Do not disable reasoning to work around a structured-output or budget problem. Use <a href="/projects/redline/get-started/configuration">model configuration</a> and the <a href="/projects/redline/local-cli#model-request-protocol">request-protocol reference</a>.</p><h2 id="an-indexer-or-related-context-is-unavailable" tabindex="-1">An indexer or related context is unavailable <a class="header-anchor" href="#an-indexer-or-related-context-is-unavailable" aria-label="Permalink to &quot;An indexer or related context is unavailable&quot;">​</a></h2><p>To run without an external indexer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span></code></pre></div><p>For indexed context, install the supported provider and Python helper separately on the trusted host. Redline does not install them for you. Unsupported versions are not silently replaced. See <a href="/projects/redline/local-cli#indexed-cross-file-context">supported versions and context modes</a>.</p><p><code>--indexing required</code> intentionally stops before model review when usable provider context is missing. Documentation and newly added files can lack a base-graph anchor. Do not interpret partial context as an exhaustive dependency search.</p><h2 id="the-review-did-not-finish" tabindex="-1">The review did not finish <a class="header-anchor" href="#the-review-did-not-finish" aria-label="Permalink to &quot;The review did not finish&quot;">​</a></h2><p>Read the per-file reasons and run status before changing budgets.</p><ul><li>A whole-run deadline can justify a larger <code>--run-timeout</code> or a smaller change.</li><li>A per-file timeout can receive a longer retry attempt within the same run budget.</li><li>Authentication, unsupported requests and output-token exhaustion need their own correction; they are not fixed by blindly retrying.</li></ul><p>Repeat the same review command to reuse eligible validated results from completed files. Failed or incomplete records are not reused as successful reviews. See <a href="/projects/redline/local-cli#review-retries-and-timeouts">retries and deadlines</a> and <a href="/projects/redline/local-cli#resume-validated-work">result reuse</a>.</p><h2 id="the-output-path-is-rejected" tabindex="-1">The output path is rejected <a class="header-anchor" href="#the-output-path-is-rejected" aria-label="Permalink to &quot;The output path is rejected&quot;">​</a></h2><p>Choose a new directory outside the reviewed repository with an existing parent. From the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../redline-review-001</span></span></code></pre></div><p>If that directory already exists, choose another name. Redline does not overwrite an earlier run.</p><h2 id="the-command-exited-zero-but-findings-are-present" tabindex="-1">The command exited zero but findings are present <a class="header-anchor" href="#the-command-exited-zero-but-findings-are-present" aria-label="Permalink to &quot;The command exited zero but findings are present&quot;">​</a></h2><p>Findings do not fail the command by default. Use <code>--fail-on findings</code>, <code>--fail-on high</code>, or <code>--fail-on critical</code> when you want a nonzero finding-policy result. Incomplete coverage still fails independently.</p><p>Read <a href="/projects/redline/results">results and exit codes</a> before treating exit code <code>0</code> as proof that the change is defect-free.</p>`,33)])])}const g=i(n,[["render",o]]);export{u as __pageData,g as default};
